/* Preserve every sign/nakshatra/sub sector instead of merging adjacent qualifying sectors. */
(()=>{'use strict';const IDS=['Su','Mo','Ma','Me','Ju','Ve','Sa','Ra','Ke'],LORDS=['Ma','Ve','Me','Mo','Su','Me','Ve','Ma','Ju','Sa','Sa','Ju'],ORDER=['Ke','Ve','Su','Mo','Ma','Ra','Ju','Sa','Me'];
function plan(selected){const display=[...new Set(selected)];if(!display.length)throw Error('Select at least one transiting planet.');if(display.some(id=>!IDS.includes(id)))throw Error('Unknown transiting planet.');return {display,scan:[...new Set([...display,'Mo','Ju','Sa'])]};}
function tracks(significators,planets=IDS,rule='star-sub',model=window.currentKPModel){const selected=new Set(significators),signOwners=new Set(significators.map(id=>['Ra','Ke'].includes(id)&&model?.planets?.some(p=>p.id===id)?KPTransitEventChains.representative(id,model):id)),fields=rule==='star'?['stl']:rule==='sub'?['sl']:rule==='star-sub'?['stl','sl']:['sgl','stl','sl'],sectors=[];for(let sign=0;sign<12;sign++)for(const star of ORDER)for(const sub of ORDER)for(const s of KPTransitEventChains.sectors([sign],star,sub)){const p={sgl:LORDS[sign],stl:star,sl:sub};if(rule==='any'?fields.some(f=>(f==='sgl'?signOwners:selected).has(p[f])):fields.every(f=>(f==='sgl'?signOwners:selected).has(p[f])))sectors.push({...s,signLord:p.sgl,...(window.KPDisplay?{signName:KPDisplay.longitudeDetails(s.lower+1).sign,nakName:KPDisplay.longitudeDetails(s.lower+1).nakshatra}:{})});}return planets.flatMap(planet=>sectors.map(s=>({id:'detail:'+planet+':'+s.sign+':'+s.nak+':'+s.subLord,planet,label:'Rashi '+(s.signName||s.sign+1)+' ('+s.signLord+') · Nakshatra '+(s.nak+1)+' ('+s.starLord+') · Sub '+s.subLord,levels:['sign','star','sub'],sector:s,test:p=>p.signIndex===s.sign&&p.nakIndex===s.nak&&p.sl===s.subLord})));}
const key=r=>['MD','AD','PD'].map(k=>r.DBA?.[k]||r.lords?.find(l=>l.level===k)?.id||'').join('/');
function intersect(a,b){const out=[];for(const x of a)for(const y of b){if(key(x)!==key(y))continue;const start=Math.max(Date.parse(x.start),Date.parse(y.start)),end=Math.min(Date.parse(x.end),Date.parse(y.end));if(end>start)out.push({...x,start:new Date(start).toISOString(),end:new Date(end).toISOString()});}return out;}
function candidates(rows,sunRows,significators=IDS){const supported=new Set(significators),valid=r=>supported.has(r.sector?.starLord)&&supported.has(r.sector?.subLord);const moon=rows.filter(r=>r.planet==='Mo'&&r.sector?.subLord===r.DBA?.PD&&supported.has(r.sector?.starLord)),jupiter=rows.filter(r=>r.planet==='Ju'&&valid(r)),saturn=rows.filter(r=>r.planet==='Sa'&&valid(r));const refined=intersect(intersect(intersect(moon,sunRows),jupiter),saturn);return {moon,refined};}
window.KPTransitEventDetail=Object.freeze({plan,tracks,candidates,intersect,ids:IDS});})();
